const assert = require('node:assert/strict');
const { test } = require('node:test');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const { run } = require('./app');

test('all standard types preserve their multipliers', () => {
  for (let index = 0; index < 30; index++) {
    for (const x of [0, -0, 1, -3, 2.5, Number.MAX_VALUE]) {
      assert.equal(run({ kind: `type${index}`, x }), x * (index + 1));
    }
  }
});

test('bonus doubles x then adds five', () => {
  for (const x of [0, -0, 1, -3, 2.5, Number.MAX_VALUE]) {
    assert.equal(run({ kind: 'bonus', x }), x * 2 + 5);
  }
});

test('only exact supported kinds are accepted', () => {
  for (const kind of [undefined, null, 0, {}, new String('type0'), 'type00',
    'type01', 'type30', 'type-1', 'type1.0', 'type1\n', 'Bonus', '',
    'toString', 'constructor', '__proto__']) {
    assert.throws(() => run({ kind, x: 1 }), /^Error: kind$/);
  }
});

test('x must be a finite primitive number and is validated first', () => {
  for (const kind of ['type0', 'type29', 'bonus', 'unknown']) {
    for (const x of [undefined, null, '2', true, {}, [], new Number(2), NaN, Infinity, -Infinity]) {
      assert.throws(() => run({ kind, x }), /^Error: x$/);
    }
  }
});

function cli(input) {
  return spawnSync(process.execPath, [path.join(__dirname, 'cli.js'), JSON.stringify(input)], {
    encoding: 'utf8',
  });
}

test('CLI retains JSON input and output for every supported kind', () => {
  for (let index = 0; index < 30; index++) {
    const result = cli({ kind: `type${index}`, x: 2.5 });
    assert.ifError(result.error);
    assert.equal(result.status, 0);
    assert.equal(result.stdout, `${JSON.stringify(2.5 * (index + 1))}\n`);
    assert.equal(result.stderr, '');
  }
  const result = cli({ kind: 'bonus', x: 3 });
  assert.ifError(result.error);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '11\n');
  assert.equal(result.stderr, '');
});

test('CLI exits unsuccessfully for invalid inputs', () => {
  for (const [input, message] of [
    [{ kind: 'unknown', x: 1 }, 'kind'],
    [{ kind: 'bonus', x: '1' }, 'x'],
  ]) {
    const result = cli(input);
    assert.ifError(result.error);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, new RegExp(`Error: ${message}`));
  }
});

