const operations = new Map(
  Array.from({ length: 30 }, (_, index) => [
    `type${index}`,
    x => x * (index + 1),
  ])
);
operations.set('bonus', x => x * 2 + 5);

function validateX(x) {
  if (typeof x !== 'number' || !Number.isFinite(x)) {
    throw Error('x');
  }
}

function getOperation(kind) {
  const operation = operations.get(kind);
  if (!operation) throw Error('kind');
  return operation;
}

function run({ kind, x }) {
  validateX(x);
  return getOperation(kind)(x);
}

module.exports = { run };
